### 📊 **Testing Steps**
<!-- Outline how your changes can be tested. Include steps, environments, or edge cases considered. -->

1.  Install Jasmine as a Dev Dependency: npm install --save-dev jasmine

2. Initialize Jasmine:  npx jasmine init

Unit Testing the Recipe Model: 

3. Create a file (for example, spec/recipeModelSpec.js) to test model validations and methods directly.

The code for Unit testing that you may include in the above file might be: `
const { sequelize, Recipe } = require('../models');

describe("Recipe Model", () => {
  // Sync the database before tests run.
  beforeAll(async () => {
    await sequelize.sync({ force: true }); // Use a test database!
  });

  it("should create a valid Recipe", async () => {
    const testRecipe = await Recipe.create({
      userId: 1, // ensure this user exists in your test db or mock it
      title: "Delicious Pie",
      ingredients: "Apples, sugar, flour",
      instructions: "Mix ingredients and bake."
    });

    expect(testRecipe.id).toBeDefined();
    expect(testRecipe.title).toEqual("Delicious Pie");
  });

  it("should throw validation error for short title", async () => {
    try {
      await Recipe.create({
        userId: 1,
        title: "Hi", // Too short, validation should fail
        ingredients: "Test ingredients",
        instructions: "Test instructions"
      });
      fail("Expected validation error");
    } catch (error) {
      expect(error.name).toEqual("SequelizeValidationError");
    }
  });
});
`

